HatBrimCurlerMaker.ironStock = 14; HatBrimCurlerMaker.bronzeStock = 12; HatBrimCurlerMaker.woodStock = 14; HatBrimCurlerMaker.leatherStock = 10; HatBrimCurlerMaker.silverStock = 8; HatBrimCurlerMaker.goldStock = 6; HatBrimCurlerMaker.jewelStock = 4; HatBrimCurlerMaker.pearlStock = 4
HatBrimCurlerMaker.productStock = {}; HatBrimCurlerMaker.buildings = {}; HatBrimCurlerMaker.maker = nil; HatBrimCurlerMaker.activeMaking = {}; HatBrimCurlerMaker.totalProducts = 0; HatBrimCurlerMaker.dayTimer = 0
function HatBrimCurlerMaker.init() HatBrimCurlerMaker.ironStock=14; HatBrimCurlerMaker.bronzeStock=12; HatBrimCurlerMaker.woodStock=14; HatBrimCurlerMaker.leatherStock=10; HatBrimCurlerMaker.silverStock=8; HatBrimCurlerMaker.goldStock=6; HatBrimCurlerMaker.jewelStock=4; HatBrimCurlerMaker.pearlStock=4; HatBrimCurlerMaker.productStock={}; HatBrimCurlerMaker.buildings={}; HatBrimCurlerMaker.maker=nil; HatBrimCurlerMaker.activeMaking={}; HatBrimCurlerMaker.totalProducts=0; HatBrimCurlerMaker.dayTimer=0; print("[HatBrimCurlerMaker] Royal Hat Brim Curler Maker System initialized (6 products, 4 buildings)") end
function HatBrimCurlerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HatBrimCurlerMaker.maker={name=n or ("Kodrnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kodrnik najet: %s (spretnost: %d)",HatBrimCurlerMaker.maker.name,s),"success") end; return true end
function HatBrimCurlerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HatBrimCurlerMaker.build(id) local ok,e=HatBrimCurlerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HatBrimCurlerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HatBrimCurlerMaker.getQualityBonus() local b=0; for _,bd in ipairs(HatBrimCurlerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HatBrimCurlerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HatBrimCurlerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HatBrimCurlerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HatBrimCurlerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HatBrimCurlerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatBrimCurlerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatBrimCurlerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatBrimCurlerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatBrimCurlerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatBrimCurlerMaker.buildings==0 then return false,"Potrebna kodrna delavnica" end; if not HatBrimCurlerMaker.maker then return false,"Potreben kodrnik" end; return true end
function HatBrimCurlerMaker.make(pt,qty) qty=qty or 1; local ok,e=HatBrimCurlerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HatBrimCurlerMaker.ironStock=HatBrimCurlerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HatBrimCurlerMaker.bronzeStock=HatBrimCurlerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HatBrimCurlerMaker.woodStock=HatBrimCurlerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HatBrimCurlerMaker.leatherStock=HatBrimCurlerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatBrimCurlerMaker.silverStock=HatBrimCurlerMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatBrimCurlerMaker.goldStock=HatBrimCurlerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatBrimCurlerMaker.jewelStock=HatBrimCurlerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatBrimCurlerMaker.pearlStock=HatBrimCurlerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatBrimCurlerMaker.maker then t=math.max(1,t-math.floor(HatBrimCurlerMaker.maker.skill/13)) end; table.insert(HatBrimCurlerMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HatBrimCurlerMaker.completeMaking(m) local q=1.0+(HatBrimCurlerMaker.getQualityBonus()/100); if HatBrimCurlerMaker.maker then q=q+(HatBrimCurlerMaker.maker.skill/140) end; q=math.min(2.5,q); HatBrimCurlerMaker.productStock[m.productType]=(HatBrimCurlerMaker.productStock[m.productType] or 0)+m.quantity; HatBrimCurlerMaker.totalProducts=HatBrimCurlerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HatBrimCurlerMaker.maker then HatBrimCurlerMaker.maker.itemsMade=HatBrimCurlerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HatBrimCurlerMaker.maker.skill=math.min(100,HatBrimCurlerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kodrnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function HatBrimCurlerMaker.update(dt) if not _G.state then return end; HatBrimCurlerMaker.dayTimer=HatBrimCurlerMaker.dayTimer+dt; if HatBrimCurlerMaker.dayTimer>=30 then HatBrimCurlerMaker.dayTimer=0; for i=#HatBrimCurlerMaker.activeMaking,1,-1 do local m=HatBrimCurlerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatBrimCurlerMaker.completeMaking(m); table.remove(HatBrimCurlerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatBrimCurlerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatBrimCurlerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HatBrimCurlerMaker.getStats() return {ironStock=HatBrimCurlerMaker.ironStock,bronzeStock=HatBrimCurlerMaker.bronzeStock,woodStock=HatBrimCurlerMaker.woodStock,leatherStock=HatBrimCurlerMaker.leatherStock,silverStock=HatBrimCurlerMaker.silverStock,goldStock=HatBrimCurlerMaker.goldStock,jewelStock=HatBrimCurlerMaker.jewelStock,pearlStock=HatBrimCurlerMaker.pearlStock,productStock=HatBrimCurlerMaker.productStock,numBuildings=#HatBrimCurlerMaker.buildings,hasMaker=HatBrimCurlerMaker.maker~=nil,makerName=HatBrimCurlerMaker.maker and HatBrimCurlerMaker.maker.name or "—",makerSkill=HatBrimCurlerMaker.maker and HatBrimCurlerMaker.maker.skill or 0,activeMaking=#HatBrimCurlerMaker.activeMaking,totalProducts=HatBrimCurlerMaker.totalProducts} end
